template SoulHarmony(n) {
  signal input orbs[n];
  signal input phase_mod;
  signal output harmony_factor;

  component orb_sum = SumOrbs(n);
  for (var i = 0; i < n; i++) {
    orb_sum.orbs[i] <== orbs[i];
  }

  signal avg_orb;
  avg_orb <== orb_sum.sum / n;

  harmony_factor <== avg_orb * phase_mod * 0.1 + 1.0;
}

template SumOrbs(n) {
  signal input orbs[n];
  signal output sum;

  component adder[n-1];
  signal intermediates[n];

  intermediates[0] <== orbs[0];
  for (var i = 0; i < n-1; i++) {
    adder[i] = Adder();
    adder[i].a <== intermediates[i];
    adder[i].b <== orbs[i+1];
    intermediates[i+1] <== adder[i].out;
  }
  sum <== intermediates[n-1];
}

template Adder {
  signal input a;
  signal input b;
  signal output out;

  out <== a + b;
}

