module Jaide.Runtime.EventLoop where

import Control.Concurrent
import Control.Monad
import Data.IORef
import System.Clock
import qualified Data.Sequence as Seq

data Event = SpikeEvent Int Int | GPUpdateEvent String deriving (Show)

newtype EventQueue = EQ { unEQ :: IORef (Seq.Seq Event) }

newEventQueue :: IO EventQueue
newEventQueue = EQ <$> newIORef Seq.empty

enqueue :: EventQueue -> Event -> IO ()
enqueue (EQ ref) ev = atomicModifyIORef' ref (\seq -> (seq Seq.|> ev, ()))

dequeue :: EventQueue -> IO (Maybe Event)
dequeue (EQ ref) = do
  seq <- atomicModifyIORef' ref (\s -> if Seq.null s then (s, s) else (Seq.viewl s, ()))
  return $ case seq of Seq.EmptyL -> Nothing; seq Seq.:<| _ -> Just seq

processSpike :: EventQueue -> Int -> Int -> IO ()
processSpike q nid sv = enqueue q (SpikeEvent nid sv)

processGPUpdate :: EventQueue -> String -> IO ()
processGPUpdate q kt = enqueue q (GPUpdateEvent kt)

eventLoop :: EventQueue -> IO ()
eventLoop q = forever $ do
  mEv <- dequeue q
  case mEv of
    Nothing -> threadDelay 10000
    Just ev -> case ev of
      SpikeEvent nid sv -> putStrLn $ "Processed spike: " ++ show nid ++ " value: " ++ show sv
      GPUpdateEvent kt -> putStrLn $ "Updated GP kernel: " ++ kt
  where
    forever act = act >> forever act

spikingLayer :: Int -> [Float] -> IO [Int]
spikingLayer size inputs = do
  q <- newEventQueue
  forkIO $ eventLoop q
  let spikes = zipWith (\i inp -> if inp > 30.0 then 1 else 0) [0..] inputs
  forM_ (zip [0..size] spikes) $ \(nid, sv) -> processSpike q nid sv
  return spikes

main :: IO ()
main = do
  spikes <- spikingLayer 128 [50.0, 20.0..]
  print spikes
package jaide.runtime

import akka.actor.{Actor, ActorSystem, Props, ActorRef}
import akka.util.Timeout
import scala.concurrent.duration._
import scala.util.Random

case class SpikeEvent(neuronId: Int, value: Int)
case class GPUpdate(kernel: String)
case class ProcessBatch(inputs: List[Float])

class Neuron(id: Int) extends Actor {
  var membrane: Float = -65.0f
  val threshold: Float = 30.0f
  val reset: Float = -70.0f
  val alpha: Float = 0.5f
  val beta: Float = 0.2f

  def receive = {
    case input: Float =>
      val dv = alpha * (membrane + 65.0f) + beta * input
      val newMem = if (membrane + dv > threshold) reset else membrane + dv
      membrane = newMem
      val spike = if (newMem > threshold) 1 else 0
      sender() ! SpikeEvent(id, spike)
    case _ => unhandled(self)
  }
}

class Layer(size: Int) extends Actor {
  val neurons = (0 until size).map(i => context.actorOf(Props(classOf[Neuron], i), s"neuron_$i"))
  var spikeCounts = Map.empty[Int, Int]

  def receive = {
    case ProcessBatch(inputs) =>
      for ((input, i) <- inputs.zipWithIndex) {
        neurons(i) ! input
      }
    case SpikeEvent(id, value) =>
      spikeCounts = spikeCounts.updated(id, spikeCounts.getOrElse(id, 0) + value)
      if (spikeCounts.values.sum % 100 == 0) {
        context.parent ! spikeCounts
      }
    case _ => unhandled(self)
  }
}

class Model(numLayers: Int, layerSize: Int) extends Actor {
  val layers = (0 until numLayers).map(i => context.actorOf(Props(classOf[Layer], layerSize), s"layer_$i"))
  implicit val timeout = Timeout(5 seconds)

  def receive = {
    case inputs: List[Float] =>
      layers.head ! ProcessBatch(inputs)
    case counts: Map[Int, Int] =>
      println(s"Received spike counts: $counts")
    case _ => unhandled(self)
  }
}

