const std = @import("std");
const crypto = std.crypto;
const mem = std.mem;
const testing = std.testing;

const Sha256 = crypto.hash.sha2.Sha256;

const ZKProof = struct {
    proof: [32]u8,
    vkey: [32]u8,
};

fn generateProof(allocator: mem.Allocator, inputs: []const u8, secret: []const u8) !ZKProof {
    var hasher = Sha256.init(.{});
    hasher.update(inputs);
    hasher.update(secret);
    var proof: [32]u8 = undefined;
    hasher.final(&proof);

    var vkey_hasher = Sha256.init(.{});
    vkey_hasher.update(secret);
    var vkey: [32]u8 = undefined;
    vkey_hasher.final(&vkey);

    return .{ .proof = proof, .vkey = vkey };
}

fn verifyProof(proof: ZKProof) bool {
    var hasher = Sha256.init(.{});
    hasher.update(&proof.vkey);
    var computed: [32]u8 = undefined;
    hasher.final(&computed);
    return mem.eql(u8, &proof.proof, &computed);
}

