pub type ZKProof {
  ZKProof(proof: String, vkey: String)
}

pub fn generate_proof(inputs: List(Int), secret: String) -> ZKProof {
  let input_bytes = inputs |> base.index_map(fn(i, v) { v |> int.to_string |> string.to_bytes })
  let combined = input_bytes ++ string.to_bytes(secret)
  let proof_hash = crypto.hash(crypto.sha256(), combined) |> base.encode_hex |> string.to_string
  let vkey_hash = crypto.hash(crypto.sha256(), string.to_bytes(secret)) |> base.encode_hex |> string.to_string
  ZKProof(proof_hash, vkey_hash)
}

pub fn verify_proof(proof: ZKProof) -> Bool {
  let computed = crypto.hash(crypto.sha256(), string.to_bytes(proof.vkey)) |> base.encode_hex
  proof.proof == computed |> string.to_string
}

pub fn main() {
  let p = generate_proof([1, 2, 3], "soul_secret")
  io.println(verify_proof(p) |> bool.to_string)
}

