use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};
use rand::Rng;

struct Neuron {
    id: u64,
    membrane: f32,
    threshold: f32,
    reset: f32,
    alpha: f32,
    beta: f32,
}

impl Neuron {
    fn new(id: u64) -> Self {
        Neuron {
            id,
            membrane: -65.0,
            threshold: 30.0,
            reset: -70.0,
            alpha: 0.5,
            beta: 0.2,
        }
    }

    fn update(&mut self, input: f32) -> i8 {
        let dv = self.alpha * (self.membrane + 65.0) + self.beta * input;
        let new_mem = if self.membrane + dv > self.threshold { self.reset } else { self.membrane + dv };
        self.membrane = new_mem;
        if new_mem > self.threshold { 1 } else { 0 }
    }
}

struct Layer {
    neurons: Vec,
}

impl Layer {
    fn new(size: usize) -> Self {
        let mut neurons = Vec::new();
        for i in 0..size {
            neurons.push(Neuron::new(i as u64));
        }
        Layer { neurons }
    }

    fn forward(&mut self, inputs: &[f32]) -> Vec {
        inputs.iter().zip(&mut self.neurons).map(|(input, neuron)| neuron.update(*input)).collect()
    }
}

struct Model {
    layers: Vec,
    weights: HashMap>,
}

impl Model {
    fn new(num_layers: usize, layer_size: usize) -> Self {
        let mut layers = Vec::new();
        for _ in 0..num_layers {
            layers.push(Layer::new(layer_size));
        }
        let mut weights = HashMap::new();
        for l in 0..num_layers {
            let mut w = vec![0.01; layer_size * layer_size];
            for i in 0..w.len() {
                w[i] = rand::thread_rng().gen_range(-0.01..0.01);
            }
            weights.insert(format!("w{}", l), w);
        }
        Model { layers, weights }
    }

    fn forward(&mut self, input: &[f32]) -> f32 {
        let mut current = input.to_vec();
        for l in 0..self.layers.len() {
            let w = self.weights.get(&format!("w{}", l)).unwrap();
            let w_mat = w.as_slice().chunks(self.layers[0].neurons.len()).collect::>();
            let mut spikes = Vec::new();
            for (i, &inp) in current.iter().enumerate() {
                let weighted = w_mat.iter().fold(0.0, |acc, row| acc + row[i] * inp);
                spikes.push(self.layers[l].neurons[i].update(weighted));
            }
            current = spikes.iter().map(|&s| s as f32).collect();
        }
        current.iter().sum::() / current.len() as f32
    }

    fn train_step(&mut self, input: &[f32], target: f32, lr: f32) {
        let output = self.forward(input);
        let loss = (output - target).powi(2);
        let grad = 2.0 * (output - target);
        for l in (0..self.layers.len()).rev() {
            let w_key = format!("w{}", l);
            if let Some(w) = self.weights.get_mut(&w_key) {
                for i in 0..w.len() {
                    w[i] -= lr * grad * input[i % input.len()] * 0.01;
                }
            }
        }
    }
}

fn main() {
    let mut model = Model::new(12, 512);
    let start = Instant::now();
    for epoch in 0..100 {
        let mut rng = rand::thread_rng();
        let input: Vec = (0..512).map(|_| rng.gen_range(-50.0..50.0)).collect();
        let target = rng.gen_range(0.0..1.0);
        model.train_step(&input, target, 0.001);
        if epoch % 10 == 0 {
            println!("Epoch {} completed", epoch);
        }
    }
    let duration = start.elapsed();
    println!("Training finished in {:?}", duration);
}
