pub type Neuron {
  Neuron(id: Int, membrane: Float, threshold: Float, reset: Float, alpha: Float, beta: Float)
}

pub fn new_neuron(id: Int) -> Neuron {
  Neuron(id, -65.0, 30.0, -70.0, 0.5, 0.2)
}

pub fn update_neuron(neuron: Neuron, input: Float) -> #(Neuron, Int) {
  let dv = neuron.alpha * (neuron.membrane + 65.0) + neuron.beta * input
  let new_mem = case neuron.membrane + dv >. neuron.threshold {
    True -> neuron.reset
    False -> neuron.membrane + dv
  }
  let spike = case new_mem >. neuron.threshold {
    True -> 1
    False -> 0
  }
  #(Neuron(..neuron, membrane: new_mem), spike)
}

pub type Layer {
  Layer(neurons: List(Neuron))
}

pub fn new_layer(size: Int) -> Layer {
  let neurons = list.map(list.range(0, size), new_neuron)
  Layer(neurons)
}

pub fn forward_layer(layer: Layer, inputs: List(Float)) -> #(Layer, List(Int)) {
  use #(neuron, input) <- list.zip(layer.neurons, inputs)
  let #(new_neuron, spike) = update_neuron(neuron, input)
  #(Layer(layer.neurons), spike)
}

pub type Model {
  Model(layers: List(Layer), weights: Map(String, List(Float)))
}

pub fn new_model(num_layers: Int, layer_size: Int) -> Model {
  let layers = list.map(list.range(0, num_layers), fn(_) { new_layer(layer_size) })
  let weights = list.map(list.range(0, num_layers), fn(l) {
    let w = list.map(list.range(0, layer_size * layer_size), fn(_) { 0.01 })
    #(string.append("w", int.to_string(l)), w)
  })
  |> map.from_list
  Model(layers, weights)
}

pub fn forward_model(model: Model, input: List(Float)) -> Float {
  use layer <- list.fold(model.layers, input)
  let #(new_layer, spikes) = forward_layer(layer, input)
  spikes
  |> list.map(int.to_float)
  |> list.sum
  |> fn(sum) { sum /. int.to_float(list.length(spikes)) }
}

pub fn train_step(model: Model, input: List(Float), target: Float, lr: Float) -> Model {
  let output = forward_model(model, input)
  let loss = (output -. target) *. (output -. target)
  let grad = 2.0 *. (output -. target)
  let new_weights = map.map_values(model.weights, fn(w_key, w) {
    list.map(w, fn(w_val) { w_val -. lr *. grad *. 0.01 })
  })
  Model(..model, weights: new_weights)
}

pub fn main() {
  let model = new_model(12, 512)
  use m <- list.fold(list.range(0, 100), model)
  let input = list.map(list.range(0, 512), fn(_) { 0.0 })
  let target = 0.5
  train_step(m, input, target, 0.001)
  io.println(#("Training complete"))
}
defmodule Jaide.Tokenizer do
  def spike_time_encode(text) do
    text
    |> String.graphemes()
    |> Enum.with_index()
    |> Enum.map(fn {char, idx} ->
      lorenz_attractor(idx, char |> :erlang.binary_to_integer(<>))
    end)
    |> List.flatten()
  end

  defp lorenz_attractor(t, seed) do
    sigma = 10.0
    rho = 28.0
    beta = 8.0 / 3.0
    dt = 0.01
    x = rem(seed, 100) / 10.0
    y = x + 1.0
    z = x + 2.0

    for _ <- 0..100 do
      dx = sigma * (y - x) * dt
      dy = (x * (rho - z) - y) * dt
      dz = (x * y - beta * z) * dt
      x = x + dx
      y = y + dy
      z = z + dz
      [x, y, z]
    end
  end

  def b_spline_interpolate(spikes, degree: 4) do
    spikes
    |> Enum.chunk_every(degree + 1, 1, :first)
    |> Enum.map(fn chunk ->
      Enum.sum(chunk) / length(chunk)
    end)
  end

  def decode_spikes(spikes) do
    spikes
    |> Enum.chunk_every(3)
    |> Enum.map(fn [x, y, z] ->
      round((x + y + z) * 10.0) |> Integer.to_charlist() |> to_string()
    end)
    |> Enum.join()
    |> String.trim()
  end

  def tokenize_full(text) do
    text
    |> spike_time_encode()
    |> b_spline_interpolate(degree: 4)
    |> decode_spikes()
  end
end

defmodule Jaide.Optimizer do
  def celestial_zoo_update(params, grad, lr, perturbation_scale, orbs) do
    harmony = Enum.sum(orbs) / length(orbs)
    effective_lr = lr * (1.0 + 0.1 * :math.sin(harmony))
    perturbation = Enum.map(grad, fn _ -> :rand.normal() * perturbation_scale end)
    loss_plus = compute_loss(params, grad, perturbation)
    loss_minus = compute_loss(params, grad, Enum.map(perturbation, &(-&1)))
    update = Enum.map(perturbation, fn p -> (loss_plus - loss_minus) / (2 * perturbation_scale) * p end)
    Enum.zip(params, update) |> Enum.map(fn {p, u} -> p - effective_lr * u end)
  end

  defp compute_loss(params, grad, perturbation) do
    Enum.zip(params, perturbation) |> Enum.map(fn {p, pert} -> p + pert end)
    |> Enum.zip(grad) |> Enum.map(fn {p, g} -> (p - g) * (p - g) end) |> Enum.sum()
  end
end

