const Neuron = struct {
    id: u64,
    membrane: f32,
    threshold: f32,
    reset: f32,
    alpha: f32,
    beta: f32,

    const Self = @This();

    pub fn init(id: u64) Self {
        return .{
            .id = id,
            .membrane = -65.0,
            .threshold = 30.0,
            .reset = -70.0,
            .alpha = 0.5,
            .beta = 0.2,
        };
    }

    pub fn update(self: *Self, input: f32) i8 {
        const dv = self.alpha * (self.membrane + 65.0) + self.beta * input;
        const new_mem = if (self.membrane + dv > self.threshold) self.reset else self.membrane + dv;
        self.membrane = new_mem;
        return if (new_mem > self.threshold) 1 else 0;
    }
};

const Layer = struct {
    neurons: []Neuron,
    allocator: Allocator,

    const Self = @This();

    pub fn init(allocator: Allocator, size: usize) !Self {
        var neurons = try allocator.alloc(Neuron, size);
        for (neurons, 0..) |*n, i| {
            n.* = Neuron.init(i);
        }
        return .{ .neurons = neurons, .allocator = allocator };
    }

    pub fn deinit(self: *Self) void {
        self.allocator.free(self.neurons);
    }

    pub fn forward(self: *Self, inputs: []const f32) ![]i8 {
        if (inputs.len != self.neurons.len) return error.SizeMismatch;
        const spikes = try self.allocator.alloc(i8, inputs.len);
        for (spikes, inputs, &self.neurons) |*s, inp, *n| {
            s.* = n.update(inp);
        }
        return spikes;
    }
};

const Model = struct {
    layers: []Layer,
    allocator: Allocator,

    const Self = @This();

    pub fn init(allocator: Allocator, num_layers: usize, layer_size: usize) !Self {
        var layers = try allocator.alloc(Layer, num_layers);
        errdefer allocator.free(layers);
        for (layers, 0..) |*l, i| {
            l.* = try Layer.init(allocator, layer_size);
        }
        return .{ .layers = layers, .allocator = allocator };
    }

    pub fn deinit(self: *Self) void {
        for (self.layers) |*l| l.deinit();
        self.allocator.free(self.layers);
    }

    pub fn forward(self: *Self, input: []const f32) !f32 {
        var current = input;
        for (self.layers) |*layer| {
            const spikes = try layer.forward(current);
            defer self.allocator.free(spikes);
            var sum: f32 = 0.0;
            for (spikes) |s| sum += @as(f32, @floatFromInt(s));
            current = &[_]f32{sum / @as(f32, @floatFromInt(current.len))};
        }
        return current[0];
    }

    pub fn train(self: *Self, input: []const f32, target: f32, lr: f32) !void {
        const output = try self.forward(input);
        const loss = math.pow(f32, output - target, 2);
        const grad = 2.0 * (output - target);
        _ = loss; // Unused
        _ = grad; // Placeholder for backprop
    }
};

