use rand::Rng;
use std::collections::HashMap;
use std::time::Instant;

struct Neuron {
    id: u64,
    membrane: f32,
    threshold: f32,
    reset: f32,
    alpha: f32,
    beta: f32,
}

impl Neuron {
    fn new(id: u64) -> Self {
        Self {
            id,
            membrane: -65.0,
            threshold: 30.0,
            reset: -70.0,
            alpha: 0.5,
            beta: 0.2,
        }
    }

    fn update(&mut self, input: f32) -> i8 {
        let dv = self.alpha * (self.membrane + 65.0) + self.beta * input;
        let next = if self.membrane + dv > self.threshold {
            self.reset
        } else {
            self.membrane + dv
        };
        self.membrane = next;
        if next > self.threshold { 1 } else { 0 }
    }
}

struct Layer {
    neurons: Vec<Neuron>,
}

impl Layer {
    fn new(size: usize) -> Self {
        let mut neurons = Vec::with_capacity(size);
        for i in 0..size {
            neurons.push(Neuron::new(i as u64));
        }
        Self { neurons }
    }

    fn forward(&mut self, inputs: &[f32]) -> Vec<i8> {
        assert_eq!(inputs.len(), self.neurons.len());
        let mut out = Vec::with_capacity(inputs.len());
        for (i, n) in self.neurons.iter_mut().enumerate() {
            out.push(n.update(inputs[i]));
        }
        out
    }
}

struct Model {
    layers: Vec<Layer>,
    weights: HashMap<String, Vec<f32>>,
    layer_size: usize,
}

impl Model {
    fn new(num_layers: usize, layer_size: usize) -> Self {
        let mut layers = Vec::with_capacity(num_layers);
        for _ in 0..num_layers {
            layers.push(Layer::new(layer_size));
        }
        let mut weights = HashMap::new();
        for l in 0..num_layers {
            let mut w = vec![0.0f32; layer_size * layer_size];
            let mut rng = rand::thread_rng();
            for v in &mut w {
                *v = rng.gen_range(-0.01f32..0.01f32);
            }
            weights.insert(format!("w{}", l), w);
        }
        Self { layers, weights, layer_size }
    }

    fn matvec(w: &[f32], size: usize, x: &[f32]) -> Vec<f32> {
        let mut y = vec![0.0f32; size];
        for j in 0..size {
            let mut acc = 0.0f32;
            let row = &w[j * size..(j + 1) * size];
            for i in 0..size {
                acc += row[i] * x[i];
            }
            y[j] = acc;
        }
        y
    }

    fn forward(&mut self, input: &[f32]) -> f32 {
        assert_eq!(input.len(), self.layer_size);
        let mut current = input.to_vec();
        for l in 0..self.layers.len() {
            let w = self.weights.get(&format!("w{}", l)).expect("missing weights");
            let weighted = Self::matvec(w, self.layer_size, &current);
            let spikes = self.layers[l].forward(&weighted);
            current.clear();
            current.extend(spikes.into_iter().map(|s| s as f32));
        }
        let s = current.iter().copied().sum::<f32>();
        s / (current.len() as f32)
    }

    fn train_step(&mut self, input: &[f32], target: f32, lr: f32) {
        let output = self.forward(input);
        let grad = 2.0f32 * (output - target);
        for l in 0..self.layers.len() {
            let key = format!("w{}", l);
            if let Some(w) = self.weights.get_mut(&key) {
                for j in 0..self.layer_size {
                    for i in 0..self.layer_size {
                        let idx = j * self.layer_size + i;
                        w[idx] -= lr * grad * input[i] * 0.01;
                    }
                }
            }
        }
    }
}

fn main() {
    let mut model = Model::new(12, 512);
    let start = Instant::now();
    let mut rng = rand::thread_rng();
    for epoch in 0..100 {
        let input: Vec<f32> = (0..512).map(|_| rng.gen_range(-50.0f32..50.0f32)).collect();
        let target: f32 = rng.gen_range(0.0f32..1.0f32);
        model.train_step(&input, target, 0.001);
        if epoch % 10 == 0 {
            println!("Epoch {} completed", epoch);
        }
    }
    let duration = start.elapsed();
    println!("Training finished in {:?}", duration);
}
